    "/api/inventory-movement": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        /**
         * Historial de movimientos con filtros por dirección y grupo
         * @description Sin filtros devuelve todos los movimientos completados. movementType filtra la dirección y group el grupo; si se envían ambos, se aplican juntos. Una combinación sin coincidencias devuelve data vacío.
         *     group=voids consulta anulados; los demás grupos consultan completados.
         *     Orden descendente por fecha de creación e id. La primera petición no envía cursor.
         *     Para la siguiente página, envía cursorDate y cursorId de nextCursor juntos y conserva los filtros. Al cambiar filtros, reinicia la paginación sin cursor.
         */
        get: {
            parameters: {
                query?: {
                    /** @description IN incluye compras, cargas iniciales y sobrantes de conteo. OUT incluye ventas, pérdidas y faltantes de conteo. Sin este filtro incluye ambas direcciones. */
                    movementType?: "IN" | "OUT";
                    /** @description Motivo exacto; se combina con group y movementType. */
                    reason?: "PURCHASE" | "SALE" | "LOSS_EXPIRED" | "LOSS_DAMAGED" | "COUNT_SURPLUS" | "COUNT_SHORTAGE" | "INITIAL_LOAD";
                    /** @description Movimientos que contienen este producto; conserva todos los artículos del movimiento. */
                    productId?: string;
                    /** @description Fecha inicial inclusiva, ISO con zona horaria. */
                    from?: string;
                    /** @description Fecha final exclusiva, posterior a from. */
                    to?: string;
                    /** @description Filtra movimientos vinculados a una caja de esta tienda. Se puede combinar con movementType y group. */
                    cashRegisterId?: string;
                    /** @description sales incluye SALE; purchase incluye PURCHASE; loss incluye LOSS_EXPIRED y LOSS_DAMAGED; count incluye COUNT_SURPLUS y COUNT_SHORTAGE; initial incluye INITIAL_LOAD. Sin grupo incluye todos los motivos completados. voids incluye anulados de cualquier motivo. */
                    group?: "sales" | "purchase" | "loss" | "count" | "initial" | "voids";
                    limit?: number;
                    /** @description Valor nextCursor.cursorId de la página anterior; enviar junto con cursorDate. */
                    cursorId?: string;
                    /** @description Valor nextCursor.cursorDate de la página anterior; enviar junto con cursorId. */
                    cursorDate?: string;
                };
                header?: never;
                path?: never;
                cookie?: never;
            };
            requestBody?: never;
            responses: {
                /** @description Historial de movimientos y cursor de la siguiente página (null si no hay más). */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["InventoryMovementsPage"];
                    };
                };
                400: components["responses"]["BadRequest"];
                401: components["responses"]["Unauthorized"];
                404: components["responses"]["CashRegisterNotFound"];
                422: components["responses"]["ValidationError"];
                500: components["responses"]["InternalError"];
                503: components["responses"]["DatabaseUnavailable"];
            };
        };
        put?: never;
        post?: never;
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
